<b>📌 متغیرهای قابل استفاده</b>
به‌جای این کدها، مقدار واقعی جایگزین می‌شود:

<b>🔹 اطلاعات کارت</b>
• <code>{name_card1}</code> و <code>{card_number1}</code> کارت اول
• <code>{name_card2}</code> و <code>{card_number2}</code> کارت دوم (و به همین شکل ۳، ۴ …)
هر کارت را هرجا و با هر فاصله‌ای که خواستید بچینید؛ خطی که به کارتی اشاره کند که ثبت نشده، کامل حذف می‌شود.

• <code>{card_number}</code> و <code>{name_card}</code> بدون شماره
اگر این دو را بدون شماره بگذارید، خطشان به‌طور خودکار برای هر کارت تکرار می‌شود (با یک خط فاصله بین‌شان).

<b>🔹 اطلاعات فاکتور</b>
• <code>{price}</code> مبلغ واریزی
• <code>{minutes}</code> مهلت پرداخت (دقیقه)

